/* ---- Solution ---- */
.stage {
  display: grid;
  place-items: center;
}

.face {
  position: relative;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background-image: radial-gradient(circle at 35% 30%, #fef08a, #facc15 60%, #eab308);
  box-shadow: inset 0 -8px 0 rgb(0 0 0 / 0.08), 0 8px 20px rgb(0 0 0 / 0.15);
}

.eye {
  position: absolute;
  top: 64px;
  width: 20px;
  height: 30px;
  border-radius: 50%;
}

.eye-left {
  left: 58px;
}

.eye-right {
  right: 58px;
}

.blush {
  position: absolute;
  top: 110px;
  width: 36px;
  height: 20px;
  border-radius: 50%;
  opacity: 0.6;
  filter: blur(4px);
}

.blush-left {
  left: 28px;
}

.blush-right {
  right: 28px;
}

.smile {
  position: absolute;
  top: 96px;
  left: 50px;
  width: 100px;
  height: 50px;
  border-bottom: 8px solid #422006;
  border-radius: 0 0 50px 50px;
}
